
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mbrxc_bg_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mbrxc_bg", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.337271312868183e+00, -4.263495886171123e+00, -4.161036072284190e+00, -4.021026645396534e+00, -3.834187465860627e+00, -3.593053748012716e+00, -3.294877585029460e+00, -2.944145802092276e+00, -2.559663443759699e+00, -2.168014024389147e+00, -1.609491616209883e+00, -7.890473599161226e-01, -6.067174376666638e-01, -5.377413255666550e-01, -4.598446478874572e-01, -4.057167000967042e-01, -4.523521178555675e-01, -7.517522840832638e-01, -2.076182565794271e+00, -1.140638546141561e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


